	title 'QD Clipping          GS ROM 2.0'*****************************************************************			   **              CLIPPING		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1987	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   *****************************************************************	include 'all.macros'	include ':QDEquates:qd.data.asm'	INCLUDE ':QDEquates:core.globals1'	INCLUDE ':QDEquates:core.globals2'	INCLUDE ':QDEquates:region.equs'	INCLUDE ':QDEquates:rect.equs';-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY Y1ToMinRect;                COPY CLIPPING/CLIPPING****************************************************************** MakeMinRect** Takes the contents of MinRect and intersects it with the* following:*                 BoundsRect*                 PortRect*                 ClipRgn Bounds Rect*                 VisRgn Bounds Rect** The resulting rectangle is left in MinRect.** Carry returns*      SET if result is null*      CLEAR if result is valid rectangle** The ClipRgn and VisRgn must already be dereferenced and* locked with pointers in RgnPtrA and RgnPtrB.*****************************************************************	EXPORT iBMakeMinRectiBMakeMinRect	PROC	jsr Y1ToMinRect	ENDP	EXPORT iMakeMinRectiMakeMinRect	PROC*              using CoreData	lda MinRect	; start with whats there	ldy #2	; region offset is 2 for top of bounds	cmp PortRect	bpl TopOK1	lda PortRectTopOk1	cmp BoundsRect	bpl TopOk2	lda BoundsRectTopOk2	cmp [RgnPtrA],y	bpl TopOk3	lda [RgnPtrA],yTopOk3	cmp [RgnPtrB],y	bpl TopOk4	lda [RgnPtrB],yTopOk4	sta MinRect	; put result back in MinRect	lda MinRect+2	iny	iny	cmp PortRect+2	bpl LeftOk1	lda PortRect+2LeftOk1	cmp BoundsRect+2	bpl LeftOk2	lda BoundsRect+2LeftOk2	cmp [RgnPtrA],y	bpl LeftOk3	lda [RgnPtrA],yLeftOk3	cmp [RgnPtrB],y	bpl LeftOk4	lda [RgnPtrB],yLeftOk4	sta MinRect+2	lda MinRect+4	iny	iny	cmp PortRect+4	bmi BottomOk1	lda PortRect+4BottomOk1	cmp BoundsRect+4	bmi BottomOk2	lda BoundsRect+4BottomOk2	cmp [RgnPtrA],y	bmi BottomOk3	lda [RgnPtrA],yBottomOk3	cmp [RgnPtrB],y	bmi BottomOk4	lda [RgnPtrB],yBottomOk4	sta MinRect+4	lda MinRect+6	iny	iny	cmp PortRect+6	bmi RightOk1	lda PortRect+6RightOk1	cmp BoundsRect+6	bmi RightOk2	lda BoundsRect+6RightOk2	cmp [RgnPtrA],y	bmi RightOk3	lda [RgnPtrA],yRightOk3	cmp [RgnPtrB],y	bmi RightOk4	lda [RgnPtrB],yRightOk4	sta MinRect+6	lda MinRect	cmp MinRect+4	bpl NullRect	lda MinRect+2	cmp MinRect+6	bpl NullRect	clcFinishIt	rtlNullRect	sec	rtl	ENDP	EXPORT MinRectToY1MinRectToY1	PROC	lda MinRect	sta Y1	lda MinRect+2	sta Y1+2	lda MinRect+4	sta Y1+4	lda MinRect+6	sta Y1+6	rts	ENDP	EXPORT Y1ToMinRectY1ToMinRect	PROC	lda Y1	sta MinRect	lda Y1+2	sta MinRect+2	lda Y1+4	sta MinRect+4	lda Y1+6	sta MinRect+6	rts	ENDP	END